import java.util.*;

public class Main {
    class AllOne {
        Map<String, Integer> counts = new HashMap<>();

        public void inc(String key) {
            counts.put(key, counts.getOrDefault(key, 0) + 1);
        }

        public void dec(String key) {
            int newCount = counts.get(key) - 1;
            if (newCount == 0) counts.remove(key);
            else counts.put(key, newCount);
        }

        public String getMaxKey() {
            if (counts.isEmpty()) return "";
            return Collections.max(counts.entrySet(), Map.Entry.comparingByValue()).getKey();  // rescans every key
        }

        public String getMinKey() {
            if (counts.isEmpty()) return "";
            return Collections.min(counts.entrySet(), Map.Entry.comparingByValue()).getKey();    // rescans every key
        }
    }

    public static void main(String[] args) {
        AllOne allOne = new AllOne();
        allOne.inc("hello");
        allOne.inc("hello");
        System.out.println(allOne.getMaxKey());
        System.out.println(allOne.getMinKey());
        allOne.inc("leet");
        System.out.println(allOne.getMaxKey());
        System.out.println(allOne.getMinKey());
    }
}

