#include <bits/stdc++.h>
using namespace std;

class AllOne {
public:
    unordered_map<string, int> counts;

    void inc(string key) {
        counts[key]++;
    }

    void dec(string key) {
        if (--counts[key] == 0) counts.erase(key);
    }

    string getMaxKey() {
        if (counts.empty()) return "";
        string best;
        int bestCount = -1;
        for (auto& entry : counts) {                                       // rescans every key every time
            if (entry.second > bestCount) { bestCount = entry.second; best = entry.first; }
        }
        return best;
    }

    string getMinKey() {
        if (counts.empty()) return "";
        string best;
        int bestCount = INT_MAX;
        for (auto& entry : counts) {                                          // rescans every key every time
            if (entry.second < bestCount) { bestCount = entry.second; best = entry.first; }
        }
        return best;
    }
};

