    AllOne allOne;
    allOne.inc("hello");
    allOne.inc("hello");
    cout << allOne.getMaxKey() << endl;
    cout << allOne.getMinKey() << endl;
    allOne.inc("leet");
    cout << allOne.getMaxKey() << endl;
    cout << allOne.getMinKey() << endl;
    return 0;
