class Node:
    def __init__(self, count):
        self.count = count
        self.keys = set()
        self.prev = None
        self.next = None

class AllOne:
    def __init__(self):
        self.head = Node(0)                                       # sentinel, before the minimum
        self.tail = Node(0)                                         # sentinel, after the maximum
        self.head.next = self.tail
        self.tail.prev = self.head
        self.key_count = {}
        self.key_node = {}

    def _insert_after(self, node, count):
        new_node = Node(count)
        new_node.prev = node
        new_node.next = node.next
        node.next.prev = new_node
        node.next = new_node
        return new_node

    def _remove_if_empty(self, node):
        if node is not self.head and node is not self.tail and not node.keys:
            node.prev.next = node.next
            node.next.prev = node.prev

    def inc(self, key):
        if key not in self.key_count:
            self.key_count[key] = 0
            self.key_node[key] = self.head
        old_node = self.key_node[key]
        new_count = self.key_count[key] + 1
        self.key_count[key] = new_count
        if old_node.next is self.tail or old_node.next.count != new_count:
            new_node = self._insert_after(old_node, new_count)           # no bucket exists yet, create one
        else:
            new_node = old_node.next                                       # reuse the existing bucket
        new_node.keys.add(key)
        self.key_node[key] = new_node
        old_node.keys.discard(key)
        self._remove_if_empty(old_node)

    def dec(self, key):
        old_node = self.key_node[key]
        new_count = self.key_count[key] - 1
        old_node.keys.discard(key)
        if new_count == 0:
            del self.key_count[key]
            del self.key_node[key]
        else:
            self.key_count[key] = new_count
            if old_node.prev is self.head or old_node.prev.count != new_count:
                new_node = self._insert_after(old_node.prev, new_count)      # no bucket exists yet, create one
            else:
                new_node = old_node.prev                                      # reuse the existing bucket
            new_node.keys.add(key)
            self.key_node[key] = new_node
        self._remove_if_empty(old_node)

    def get_max_key(self):
        return next(iter(self.tail.prev.keys)) if self.tail.prev is not self.head else ""

    def get_min_key(self):
        return next(iter(self.head.next.keys)) if self.head.next is not self.tail else ""


if __name__ == "__main__":
    all_one = AllOne()
