import java.util.*;

public class Main {
    class Node {
        int count;
        Set<String> keys = new HashSet<>();
        Node prev, next;
        Node(int count) { this.count = count; }
    }

    class AllOne {
        Node head = new Node(0), tail = new Node(0);                       // sentinels, before min and after max
        Map<String, Integer> keyCount = new HashMap<>();
        Map<String, Node> keyNode = new HashMap<>();

        public AllOne() {
            head.next = tail;
            tail.prev = head;
        }

        Node insertAfter(Node node, int count) {
            Node newNode = new Node(count);
            newNode.prev = node;
            newNode.next = node.next;
            node.next.prev = newNode;
            node.next = newNode;
            return newNode;
        }

        void removeIfEmpty(Node node) {
            if (node != head && node != tail && node.keys.isEmpty()) {
                node.prev.next = node.next;
                node.next.prev = node.prev;
            }
        }

        public void inc(String key) {
            if (!keyCount.containsKey(key)) {
                keyCount.put(key, 0);
                keyNode.put(key, head);
            }
            Node oldNode = keyNode.get(key);
            int newCount = keyCount.get(key) + 1;
            keyCount.put(key, newCount);
            Node newNode = (oldNode.next == tail || oldNode.next.count != newCount)
                ? insertAfter(oldNode, newCount)                                 // no bucket exists yet, create one
                : oldNode.next;                                                   // reuse the existing bucket
            newNode.keys.add(key);
            keyNode.put(key, newNode);
            oldNode.keys.remove(key);
            removeIfEmpty(oldNode);
        }

        public void dec(String key) {
            Node oldNode = keyNode.get(key);
            int newCount = keyCount.get(key) - 1;
            oldNode.keys.remove(key);
            if (newCount == 0) {
                keyCount.remove(key);
                keyNode.remove(key);
            } else {
                keyCount.put(key, newCount);
                Node newNode = (oldNode.prev == head || oldNode.prev.count != newCount)
                    ? insertAfter(oldNode.prev, newCount)                            // no bucket exists yet, create one
                    : oldNode.prev;                                                    // reuse the existing bucket
                newNode.keys.add(key);
                keyNode.put(key, newNode);
            }
            removeIfEmpty(oldNode);
        }

        public String getMaxKey() {
            return tail.prev == head ? "" : tail.prev.keys.iterator().next();
        }

        public String getMinKey() {
            return head.next == tail ? "" : head.next.keys.iterator().next();
        }
    }

    public static void main(String[] args) {
        AllOne allOne = new AllOne();
        allOne.inc("hello");
        allOne.inc("hello");
        System.out.println(allOne.getMaxKey());
        System.out.println(allOne.getMinKey());
        allOne.inc("leet");
        System.out.println(allOne.getMaxKey());
        System.out.println(allOne.getMinKey());
    }
