#include <bits/stdc++.h>
using namespace std;

struct Node {
    int count;
    unordered_set<string> keys;
    Node* prev = nullptr;
    Node* next = nullptr;
    Node(int c) : count(c) {}
};

class AllOne {
public:
    Node* head;
    Node* tail;
    unordered_map<string, int> keyCount;
    unordered_map<string, Node*> keyNode;

    AllOne() {
        head = new Node(0);
        tail = new Node(0);
        head->next = tail;
        tail->prev = head;
    }

    Node* insertAfter(Node* node, int count) {
        Node* newNode = new Node(count);
        newNode->prev = node;
        newNode->next = node->next;
        node->next->prev = newNode;
        node->next = newNode;
        return newNode;
    }

    void removeIfEmpty(Node* node) {
        if (node != head && node != tail && node->keys.empty()) {
            node->prev->next = node->next;
            node->next->prev = node->prev;
        }
    }

    void inc(string key) {
        if (!keyCount.count(key)) {
            keyCount[key] = 0;
            keyNode[key] = head;
        }
        Node* oldNode = keyNode[key];
        int newCount = keyCount[key] + 1;
        keyCount[key] = newCount;
        Node* newNode = (oldNode->next == tail || oldNode->next->count != newCount)
            ? insertAfter(oldNode, newCount)                                    // no bucket exists yet, create one
            : oldNode->next;                                                      // reuse the existing bucket
        newNode->keys.insert(key);
        keyNode[key] = newNode;
        oldNode->keys.erase(key);
        removeIfEmpty(oldNode);
    }

    void dec(string key) {
        Node* oldNode = keyNode[key];
        int newCount = keyCount[key] - 1;
        oldNode->keys.erase(key);
        if (newCount == 0) {
            keyCount.erase(key);
            keyNode.erase(key);
        } else {
            keyCount[key] = newCount;
            Node* newNode = (oldNode->prev == head || oldNode->prev->count != newCount)
                ? insertAfter(oldNode->prev, newCount)                               // no bucket exists yet, create one
                : oldNode->prev;                                                       // reuse the existing bucket
            newNode->keys.insert(key);
            keyNode[key] = newNode;
        }
        removeIfEmpty(oldNode);
    }

    string getMaxKey() {
        return tail->prev == head ? "" : *tail->prev->keys.begin();
    }

    string getMinKey() {
        return head->next == tail ? "" : *head->next->keys.begin();
    }
};

int main() {
    AllOne allOne;
    allOne.inc("hello");
    allOne.inc("hello");
    cout << allOne.getMaxKey() << endl;
    cout << allOne.getMinKey() << endl;
    allOne.inc("leet");
    cout << allOne.getMaxKey() << endl;
